// requester
zmq::socket_t req(ctx, zmq::socket_type::req);
req.connect("tcp://127.0.0.1:5555");
req.send(zmq::buffer("fib:10"));          // routing envelope is implicit
zmq::message_t reply; req.recv(reply);

// service: REP remembers the address of the last request
zmq::socket_t srv(ctx, zmq::socket_type::rep);
srv.bind("tcp://127.0.0.1:5555");
zmq::message_t request; srv.recv(request);
srv.send(zmq::buffer(std::to_string(fib(10))));   // routed to that peer

// ROUTER service: frames = [routing-id][empty][body]
zmq::message_t id, delim, body;
router.recv(id); router.recv(delim); router.recv(body);
// the routing id IS the return address; keep it with the request
pending.emplace_back(std::move(id), fib(*body.data<int>()));
// later, possibly on another thread:
router.send(pending.front().id, zmq::send_flags::sndmore);
router.send(zmq::buffer(std::string()), zmq::send_flags::sndmore);
router.send(zmq::buffer(std::to_string(pending.front().answer)));

